def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full horizontal bars encode a row-periodic pattern.
    bars = {}
    for r, row in enumerate(grid):
        if row and row[0] != 0 and all(v == row[0] for v in row):
            bars[r] = row[0]
    if bars:
        period = len(bars)
        motif = {r % period: color for r, color in bars.items()}
        if len(motif) == period:
            return [[motif[r % period] for _ in range(w)] for r in range(h)]

    # Otherwise the clues are parallel diagonals. Choose their orientation by
    # grouping cells on the two diagonal invariants, r-c and r+c.
    cells = [(r, c, v) for r, row in enumerate(grid)
             for c, v in enumerate(row) if v != 0]
    if not cells:
        return [row[:] for row in grid]

    tracks_down = {}
    tracks_up = {}
    for r, c, color in cells:
        tracks_down.setdefault(r - c, []).append(color)
        tracks_up.setdefault(r + c, []).append(color)

    def score(tracks):
        # Long parallel segments and multiple colored tracks characterize the
        # encoded orientation; single-cell incidental diagonals score poorly.
        return (sum(len(v) * len(v) for v in tracks.values()), len(tracks))

    invariant, tracks = (('down', tracks_down) if score(tracks_down) >= score(tracks_up)
                         else ('up', tracks_up))
    track_colors = {}
    for key, colors in tracks.items():
        unique = set(colors)
        if len(unique) == 1:
            track_colors[key] = next(iter(unique))
        else:
            # A clue track should be monochrome; preserve the most frequent color.
            track_colors[key] = max(unique, key=colors.count)

    period = len(track_colors)
    if not period:
        return [row[:] for row in grid]
    motif = {key % period: color for key, color in track_colors.items()}
    if len(motif) != period:
        return [row[:] for row in grid]

    if invariant == 'down':
        return [[motif[(r - c) % period] for c in range(w)] for r in range(h)]
    return [[motif[(r + c) % period] for c in range(w)] for r in range(h)]
